mapper.select:
SELECT cr.commission_rule_id, cr.commission_item_id, cr.fee_component_type, cr.agent_rank_code, cr.installment_from, cr.installment_to, cr.basis_code, cr.calculation_type, cr.rate_pct, cr.fixed_amount, cr.rounding_scale, cr.rounding_mode, cr.payment_condition_code, cr.insurer_id, cr.organization_id, cr.product_offering_id, cr.priority_no
FROM commission_rule cr JOIN insurance_contract c ON c.contract_id = #{contractId}
WHERE cr.policy_version_id = #{policyVersionId} AND cr.payment_stage = #{paymentStage} AND (cr.insurer_id IS NULL OR cr.insurer_id = c.insurer_id ) AND (cr.product_offering_id IS NULL OR cr.product_offering_id = c.product_offering_id ) AND (cr.organization_id IS NULL OR cr.organization_id = c.organization_id ) ORDER BY cr.priority_no ASC, cr.installment_from ASC, cr.commission_rule_id ASC

SELECT
FROM fgc.policy_version pv LEFT JOIN fgc.app_user cb ON cb.user_id = pv.created_by LEFT JOIN fgc.app_user ab ON ab.user_id = pv.approved_by
AND pv.policy_type = #{type}
AND pv.status = #{status}
AND pv.effective_from <= #{asOf} AND (pv.effective_to IS NULL OR pv.effective_to >= #{asOf})
ORDER BY pv.policy_code, pv.version_no
